WITH flattened_attrs AS (SELECT id, customer_id, created_at, ship_to, attributes, SIZE(items) AS num_items, ship_to.city AS ship_city FROM carts WHERE HOUR(created_at) BETWEEN 8 AND 13) SELECT id, customer_id, created_at, ship_to, attributes, num_items, ship_city, SUM(num_items) OVER (ORDER BY created_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_num_items, MAX(num_items) OVER (PARTITION BY customer_id ORDER BY CAST(created_at AS BIGINT) ASC RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS num_items_max_2h, NTILE(3) OVER (PARTITION BY customer_id ORDER BY num_items DESC, id ASC) AS num_items_bucket FROM flattened_attrs;
